// === Tab: mySketch.js ===
// Arrays to hold rain objects
let drops = [];     // background rain (behind FG)
let fgDrops = [];   // foreground rain (in front of FG)

let bg;
let fg;

function preload() {
	// Preloads the 2 necessary images so they are ready before the sketch starts. The forground image has a transparent background
	// This means it sits on top of the background, and creates a layer effect

	// The character and world showcased in this Sketch was created from scratch using Open-Source 3 model tool Blender and Unreal Engine 5. This entire process is being documented at keithmahony.com
	// This sketch was an attempt to combine Unreal Engine with yet another open-source technology, p5js. 


  bg = loadImage("https://openprocessing.org/sketch/2771309/files/NY_BG.png"); // background image
  fg = loadImage("https://openprocessing.org/sketch/2771309/files/NY_FG.png"); // foreground image
}

function setup() {
  createCanvas(windowWidth, windowHeight); // window matches the size of the available window

  // This creates the rain, but has been repurposed to add 'background' rain only 
  // The background has more rain overall to appear denser
  for (let i = 0; i < 1000; i++)drops.push(new Drop());

  // This creates rain, but has been duplicated so there can be a secondary source
  // This second source is lighter (<120) and only displays in the forground.
  for (let i = 0; i < 120; i++) fgDrops.push(new ForegroundDrop());
}

function draw() {
  background(0);

  // Identifies correct scale to cover entire canvas (without stretching either image or having visible margins)
  let scaleX = width / bg.width;
  let scaleY = height / bg.height;
  let scaleFactor = max(scaleX, scaleY); // choose larger scale to cover canvas
  let imgW = bg.width * scaleFactor;
  let imgH = bg.height * scaleFactor;
  let imgX = (width - imgW) / 2; // center image horizontally
  let imgY = (height - imgH) / 2;// center image vertically

  // Draw background image (layer 0)
  image(bg, imgX, imgY, imgW, imgH);

  // Slightly dark overlay added for mood (layer 1)
  fill(0, 60);
  noStroke();
  rect(0, 0, width, height);

  // Draw background rain (layer 2)
  for (let d of drops) {
    d.update();
    d.show();
  }

  // Draw foreground image (layer 3)
  image(fg, imgX, imgY, imgW, imgH);

  // Draw foreground rain (layer 4)
  for (let d of fgDrops) {
    d.update();
    d.show();
  }
}

// Background Drops (Layer 2)

class Drop {
  constructor() {
    this.reset(); // initialize position and speed
    this.splashTimer = 0; // for splash animation when hitting bottom
  }

  reset() {
	 // Position randomly above screen
    this.x = random(width);
    this.y = random(-height, 0);
    this.z = random(0, 15); // // Depth for visual effect
    this.len = map(this.z, 0, 15, 10, 30); // longer
    this.yspeed = map(this.z, 0, 15, 3, 15); // faster
    this.opacity = map(this.z, 0, 15, 20, 40); // more visible
  }

  update() {
    this.y += this.yspeed; // move drop down
    this.x += map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -0.5, 0.5); //  wind effect (I think!)

    if (this.y > height) { // if drop reaches bottom
      this.splashTimer = 1; // start splash animation
      this.splashX = this.x; // position of splash
      this.splashY = height - 5; // I can adjust drop draw position here
      this.reset();  // reset drop to top
    }

    if (this.splashTimer > 0) { // animate splash
      this.splashTimer++;
      if (this.splashTimer > 8) this.splashTimer = 0; // stop splash 
    }
  }

  show() {
    stroke(255, 220, 180, this.opacity); // changed from blue to light yellowish color - match environment
    strokeWeight(map(this.z, 0, 15, 0.5, 1.5)); // thicker for closer drops (foreground)
    line(this.x, this.y, this.x, this.y + this.len);

    if (this.splashTimer > 0) { // draw splash if active
      noFill();
      stroke(255, 255, 255, 30 - this.splashTimer * 5);
      ellipse(
        this.splashX,
        this.splashY,
        this.splashTimer * 3,
        this.splashTimer
      );
    }
  }
}

// Foreground Drop class (layer 4)

class ForegroundDrop {
  constructor() {
    this.reset();
  }

  reset() {
	// Position randomly above canvas
    this.x = random(width);
    this.y = random(-height, 0);
    this.len = random(25, 30); // longer drops
    this.speed = random(15, 15); //constant speed (testing random but constant looks better?)
    this.alpha = random(15, 25); // transparency
    this.weight = random(2, 3);// thickness
  }

  update() {
	  // Mouse-controlled slow time (just slows speed of rain)
    let speedFactor = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0.2, 2);
    this.y += this.speed * speedFactor;

    if (this.y > height) this.reset(); // recycle drop to top (dont have to draw them again)
  }

  show() {
    stroke(255, 220, 180, this.alpha);
    strokeWeight(this.weight);
    line(this.x, this.y, this.x, this.y + this.len);
  }
}

